    for b2 in bases:
        for b3 in bases:
            code[b1+b2+b3]=aas[i]; i+=1
def tr(s): return "".join(code.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))

def orfs_all(minaa):
    out=[]
    for strand in (1,-1):
        s = seq if strand==1 else rc(seq)
        for f in range(3):
            i=f
            while i<len(s)-2:
                if s[i:i+3] in ("ATG","GTG","TTG"):
                    j=i
                    while j<len(s)-2 and s[j:j+3] not in ("TAA","TAG","TGA"): j+=3
                    prot=tr(s[i:j+3])
                    if len(prot)-1>=minaa:
                        if strand==1: start,end=(i+1),(j+3)
                        else: start,end=(len(seq)-j),(len(seq)-i)
                        out.append((strand,f+1,start,end,prot[:-1]))
                    i=j+3
                else: i+=3
    # dedupe
    seen=set(); res=[]
    for o in out:
        key=(o[0],o[2],o[3])
        if key in seen: continue
        seen.add(key); res.append(o)
    return res

