    for b2 in bases:
        for b3 in bases:
            code[b1+b2+b3]=aas[i]; i+=1
def tr(s): return "".join(code.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))

def find(strand, minaa, starts=("ATG","GTG","TTG")):
    s = seq if strand==1 else rc(seq)
    n=len(s)
    res=[]
    for f in range(3):
        i=f
        while i < n-2:
            if s[i:i+3] in starts:
                j=i
                while j<n-2 and s[j:j+3] not in ("TAA","TAG","TGA"):
                    j+=3
                aa=(j-i)//3
                prot=tr(s[i:min(j+3,n)])
                truncated = (j+3>n)
                if aa>=minaa:
                    if strand==1:
                        gs,ge=i+1, min(j+3,n)
                    else:
                        gs,ge = L-(min(j+3,n))+1, L-i
                    res.append((strand,f+1,gs,ge,aa,prot,truncated,s[i:i+3]))
                i=j+3
            else: i+=3
    return res

allorf = find(1,60)+find(-1,60)
