def open_intervals(s, f, strand, minlen=90):
    # returns genomic intervals (1-based) that are stop-free in frame f
    res=[]
    n=len(s)
    # positions of stops
    start=f
    pos=f
    segs=[]
    i=f
    last=f
    while i < n-2:
