            segs.append((last, i))  # codon indices
            last=i+3
        i+=3
    segs.append((last, n))
    for a,b in segs:
        if b-a>=minlen:
            if strand==1: gs,ge=a+1, min(b,n)
            else: gs,ge = L-min(b,n)+1, L-a
            res.append((gs,ge,b-a))
    return res
