# ---- correct stop-free intervals per strand/frame ----
# For plus strand: codon k occupies positions (f+3k+1 .. f+3k+3) 1-based.
# For minus strand: we read revcomp; codon with first base at mf index i corresponds to genomic bases (L-i), (L-i-1), (L-i-2)
def stops_plus(f):
    return [ (f+3*k)//3 for k in range((L-f)//3) if seq[f+3*k:f+3*k+3] in ("TAA","TAG","TGA")]
def intervals_plus(f, minnt=60):
    segs=[]
    start=f
    pos=f
    while pos < L-2:
        if seq[pos:pos+3] in ("TAA","TAG","TGA"):
            if pos-start>=minnt: segs.append((start+1,pos))
            start=pos+3
        pos+=3
    if L-start>=minnt: segs.append((start+1,L))
    return segs
def intervals_minus(f, minnt=60):
    mf=rc(seq)
    segs=[]
    start=f; pos=f
    while pos < L-2:
        if mf[pos:pos+3] in ("TAA","TAG","TGA"):
            if pos-start>=minnt:
                # genomic interval: mf [start,pos) -> genomic [L-pos+1, L-start]
                segs.append((L-pos+1, L-start))
            start=pos+3
        pos+=3
    if L-start>=minnt: segs.append((1, L-start))
    return segs
print("=== stop-free stretches >= 60 nt (correct coordinates) ===")
for f in range(3):
    print("plus frame",f+1, sorted(intervals_plus(f)))
for f in range(3):
