        for b3 in bases: code[b1+b2+b3]=aas[i]; i+=1
stops=("TAA","TAG","TGA")
START=("ATG","GTG","TTG","ATT","CTG")

def orfs_minus():
    out=[]
    for r in range(3):
        g = L - ((L-r)%3)   # highest codon base with g%3==r
        while g>=3:
            c=rc(seq[g-3:g])
            if c in START:
                gg=g; prot=""
                while gg>=3:
                    cc=rc(seq[gg-3:gg])
                    if cc in stops: break
                    prot+=code[cc]; gg-=3
                out.append((gg+1, g, prot, c, rc(seq[gg-3:gg]) if gg>=3 else None))
                g=gg-3
            else:
                g-=3
    return out
def orfs_plus():
    out=[]
    for r in range(3):
        p=r+1
        while p<=L-2:
            c=seq[p-1:p+2]
            if c in START:
                q=p; prot=""
                while q<=L-2:
                    cc=seq[q-1:q+2]
                    if cc in stops: break
                    prot+=code[cc]; q+=3
                out.append((p, q+2, prot, c, seq[q-1:q+2] if q<=L-2 else None))
                p=q+3
            else: p+=3
    return out

